import { SettingsPage } from "@/components/settings-page";

export default function Page() {
  return (
    <div className="min-h-svh bg-background">
      <SettingsPage />
    </div>
  );
}

import type { Profile, Session } from "@/components/settings-model";

export const SAVED_PROFILE: Profile = {
  email: "ada@keystoneui.io",
  name: "Ada Lovelace",
};

export const SESSIONS: Session[] = [
  {
    current: true,
    device: "Chrome on macOS",
    id: "s1",
    lastActive: "Now",
    location: "London, UK",
  },
  {
    current: false,
    device: "Safari on iPhone",
    id: "s2",
    lastActive: "2 hours ago",
    location: "London, UK",
  },
  {
    current: false,
    device: "Firefox on Windows",
    id: "s3",
    lastActive: "3 days ago",
    location: "Bucharest, RO",
  },
];

export const NOTIFICATIONS = [
  {
    description: "Sign-ins from a new device or location.",
    id: "security",
    label: "Security alerts",
    locked: true,
  },
  {
    description: "A weekly summary of activity across your workspaces.",
    id: "digest",
    label: "Weekly digest",
    locked: false,
  },
  {
    description: "Product updates and the occasional announcement.",
    id: "product",
    label: "Product news",
    locked: false,
  },
] as const;

/**
 * The rules behind settings-01, separate from the UI so they can be tested.
 */

export interface Profile {
  email: string;
  name: string;
}

export interface Session {
  current: boolean;
  device: string;
  id: string;
  lastActive: string;
  location: string;
}

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

/** Field errors for a profile draft; an empty object means it can be saved. */
export function validateProfile(
  profile: Profile
): Partial<Record<keyof Profile, string>> {
  const errors: Partial<Record<keyof Profile, string>> = {};
  if (profile.name.trim().length === 0) {
    errors.name = "Enter your name.";
  }
  if (!EMAIL_RE.test(profile.email.trim())) {
    errors.email = "Enter an email address like name@example.com.";
  }
  return errors;
}

/** The fields a draft changes, ignoring whitespace the user cannot see. */
export function changedFields(
  saved: Profile,
  draft: Profile
): (keyof Profile)[] {
  return (Object.keys(saved) as (keyof Profile)[]).filter(
    (key) => saved[key].trim() !== draft[key].trim()
  );
}

/**
 * Deleting an account asks for its email typed back, case-insensitively,
 * so the destructive button is a deliberate act rather than a reflex.
 */
export function confirmsDeletion(email: string, typed: string): boolean {
  return typed.trim().toLowerCase() === email.trim().toLowerCase();
}

/** Every session except the current one — "Sign out other sessions". */
export function otherSessions(sessions: readonly Session[]): Session[] {
  return sessions.filter((s) => !s.current);
}

"use client";

import { useState } from "react";
import {
  NOTIFICATIONS,
  SAVED_PROFILE,
  SESSIONS,
} from "@/components/mock-account";
import {
  changedFields,
  confirmsDeletion,
  otherSessions,
  type Profile,
  validateProfile,
} from "@/components/settings-model";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from "@/components/ui/alert-dialog";
import { Avatar, AvatarFallback } from "@/components/ui/avatar";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardFooter,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Field,
  FieldContent,
  FieldDescription,
  FieldError,
  FieldGroup,
  FieldLabel,
} from "@/components/ui/field";
import { Input } from "@/components/ui/input";
import { Switch } from "@/components/ui/switch";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

function initials(name: string): string {
  return name
    .split(" ")
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join("");
}

function ProfileCard() {
  const [saved, setSaved] = useState(SAVED_PROFILE);
  const [draft, setDraft] = useState(SAVED_PROFILE);
  const [submitted, setSubmitted] = useState(false);

  const errors = validateProfile(draft);
  const dirty = changedFields(saved, draft).length > 0;
  const showErrors = submitted;

  const update = (key: keyof Profile) => (value: string) =>
    setDraft((prev) => ({ ...prev, [key]: value }));

  return (
    <Card>
      <CardHeader>
        <CardTitle>Profile</CardTitle>
        <CardDescription>How you appear to your team.</CardDescription>
      </CardHeader>
      <CardContent>
        <form
          id="profile-form"
          noValidate
          onSubmit={(event) => {
            event.preventDefault();
            setSubmitted(true);
            if (Object.keys(errors).length === 0) {
              const clean = {
                email: draft.email.trim(),
                name: draft.name.trim(),
              };
              setSaved(clean);
              setDraft(clean);
              setSubmitted(false);
            }
          }}
        >
          <FieldGroup>
            <div className="flex items-center gap-3">
              <Avatar className="size-12">
                <AvatarFallback>{initials(saved.name)}</AvatarFallback>
              </Avatar>
              <div className="text-sm">
                <p className="font-medium">{saved.name}</p>
                <p className="text-muted-foreground">{saved.email}</p>
              </div>
            </div>
            <Field data-invalid={showErrors && errors.name ? true : undefined}>
              <FieldLabel htmlFor="settings-name">Name</FieldLabel>
              <Input
                aria-invalid={showErrors && Boolean(errors.name)}
                id="settings-name"
                onChange={(event) => update("name")(event.target.value)}
                value={draft.name}
              />
              {showErrors && errors.name ? (
                <FieldError>{errors.name}</FieldError>
              ) : null}
            </Field>
            <Field data-invalid={showErrors && errors.email ? true : undefined}>
              <FieldLabel htmlFor="settings-email">Email</FieldLabel>
              <Input
                aria-invalid={showErrors && Boolean(errors.email)}
                id="settings-email"
                onChange={(event) => update("email")(event.target.value)}
                type="email"
                value={draft.email}
              />
              {showErrors && errors.email ? (
                <FieldError>{errors.email}</FieldError>
              ) : null}
            </Field>
          </FieldGroup>
        </form>
      </CardContent>
      <CardFooter className="justify-end gap-2 border-t">
        <Button
          disabled={!dirty}
          onClick={() => {
            setDraft(saved);
            setSubmitted(false);
          }}
          size="sm"
          variant="ghost"
        >
          Cancel
        </Button>
        <Button disabled={!dirty} form="profile-form" size="sm" type="submit">
          Save changes
        </Button>
      </CardFooter>
    </Card>
  );
}

function NotificationsCard() {
  const [enabled, setEnabled] = useState<Record<string, boolean>>({
    digest: true,
    product: false,
    security: true,
  });

  return (
    <Card>
      <CardHeader>
        <CardTitle>Notifications</CardTitle>
        <CardDescription>Email we send you, and when.</CardDescription>
      </CardHeader>
      <CardContent>
        <FieldGroup>
          {NOTIFICATIONS.map((n) => (
            <Field key={n.id} orientation="horizontal">
              <FieldContent>
                <FieldLabel htmlFor={`notify-${n.id}`}>{n.label}</FieldLabel>
                <FieldDescription>
                  {n.description}
                  {n.locked ? " Always on for your account's safety." : null}
                </FieldDescription>
              </FieldContent>
              <Switch
                checked={enabled[n.id]}
                disabled={n.locked}
                id={`notify-${n.id}`}
                onCheckedChange={(checked) =>
                  setEnabled((prev) => ({ ...prev, [n.id]: checked }))
                }
              />
            </Field>
          ))}
        </FieldGroup>
      </CardContent>
    </Card>
  );
}

function SignedInSessionsCard() {
  const [sessions, setSessions] = useState(SESSIONS);
  const others = otherSessions(sessions);

  return (
    <Card>
      <CardHeader>
        <CardTitle>Sessions</CardTitle>
        <CardDescription>
          Devices signed in to your account. Sign out any you do not recognise.
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Table size="sm">
          <TableHeader>
            <TableRow>
              <TableHead>Device</TableHead>
              <TableHead className="hidden sm:table-cell">Location</TableHead>
              <TableHead>Last active</TableHead>
              <TableHead className="w-0">
                <span className="sr-only">Actions</span>
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {sessions.map((s) => (
              <TableRow key={s.id}>
                <TableCell className="font-medium">
                  {s.device}
                  {s.current ? (
                    <Badge className="ms-2" variant="secondary">
                      This device
                    </Badge>
                  ) : null}
                </TableCell>
                <TableCell className="hidden text-muted-foreground sm:table-cell">
                  {s.location}
                </TableCell>
                <TableCell className="text-muted-foreground">
                  {s.lastActive}
                </TableCell>
                <TableCell className="text-end">
                  {s.current ? null : (
                    <Button
                      aria-label={`Sign out ${s.device}`}
                      onClick={() =>
                        setSessions((prev) => prev.filter((x) => x.id !== s.id))
                      }
                      size="sm"
                      variant="ghost"
                    >
                      Sign out
                    </Button>
                  )}
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      </CardContent>
      <CardFooter className="justify-end border-t">
        <Button
          disabled={others.length === 0}
          onClick={() => setSessions((prev) => prev.filter((s) => s.current))}
          size="sm"
          variant="outline"
        >
          Sign out other sessions
        </Button>
      </CardFooter>
    </Card>
  );
}

function DangerZoneCard() {
  const [typed, setTyped] = useState("");
  const [deleted, setDeleted] = useState(false);
  const email = SAVED_PROFILE.email;

  return (
    <Card className="ring-destructive/30">
      <CardHeader>
        <CardTitle>Delete account</CardTitle>
        <CardDescription>
          {deleted
            ? "Account scheduled for deletion. You have 30 days to change your mind."
            : "Permanently remove your account and everything in it."}
        </CardDescription>
      </CardHeader>
      <CardFooter className="justify-end border-t">
        <AlertDialog onOpenChange={(open) => (open ? null : setTyped(""))}>
          <AlertDialogTrigger
            disabled={deleted}
            render={<Button size="sm" variant="destructive" />}
          >
            Delete account
          </AlertDialogTrigger>
          <AlertDialogContent>
            <AlertDialogHeader>
              <AlertDialogTitle>Delete your account?</AlertDialogTitle>
              <AlertDialogDescription>
                This removes your profile, sessions and workspaces after 30
                days. Type <strong>{email}</strong> to confirm.
              </AlertDialogDescription>
            </AlertDialogHeader>
            <Input
              aria-label="Type your email to confirm"
              autoComplete="off"
              onChange={(event) => setTyped(event.target.value)}
              value={typed}
            />
            <AlertDialogFooter>
              <AlertDialogCancel>Cancel</AlertDialogCancel>
              <AlertDialogAction
                disabled={!confirmsDeletion(email, typed)}
                onClick={() => setDeleted(true)}
                variant="destructive"
              >
                Delete account
              </AlertDialogAction>
            </AlertDialogFooter>
          </AlertDialogContent>
        </AlertDialog>
      </CardFooter>
    </Card>
  );
}

export function SettingsPage() {
  return (
    <div className="mx-auto flex w-full max-w-2xl flex-col gap-6 p-6">
      <div>
        <h1 className="font-semibold text-2xl tracking-tight">Settings</h1>
        <p className="text-muted-foreground text-sm">
          Manage your profile, notifications and sessions.
        </p>
      </div>
      <ProfileCard />
      <NotificationsCard />
      <SignedInSessionsCard />
      <DangerZoneCard />
    </div>
  );
}
